Item.Data:
&lt;?xml version="1.0" encoding="utf-8" ?&gt;
&lt;AssignedAccessConfiguration 
    xmlns="http://schemas.microsoft.com/AssignedAccess/2017/config"
    xmlns:rs5="http://schemas.microsoft.com/AssignedAccess/201810/config"
    xmlns:r1809="http://schemas.microsoft.com/AssignedAccess/201810/config"
    &gt;
    &lt;Profiles&gt;
        &lt;Profile Id="{2d37d0db-19a0-48ad-8b8b-976a7cbf556d}"&gt;
            &lt;AllAppsList&gt;
                &lt;AllowedApps&gt;
                    &lt;!-- Applications --&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"/&gt;

                    &lt;!-- Workspace ONE Agent & Assist --&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AW.ProtectionAgent.PowershellExecutor64.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AW.ProtectionAgent.PowershellExecutor86.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AW.Win32.ModernApp.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AW.WinPC.Updater.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AWACMClient.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AWProcessCommands.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\AwWindowsIpc.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\CertificateWinForm.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\NativeEnrollment.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\StorageUpgrade.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\TaskScheduler.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\UEM\X64\UEMBaselines.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\UEM\X86\UEMBaselines.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\Win32AgentIPC.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\AgentUI\WorkspaceONE.Hub.Win32Agent.AppXInstaller.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\Deem\Omnissa-Telemetry-Agent.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\Dem\DemEnterprise-x64.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\HealthMonitoring\WorkspaceONEHubHealthMonitoring.exe"/&gt;
                    &lt;App DesktopAppPath="C:\Program Files (x86)\Airwatch\Sfd\AppDeploymentAgent-x64.exe"/&gt;
                    &lt;App AppUserModelId="AirWatchLLC.WorkspaceONEIntelligentHub_htcwkw4rx2gx4!App"/&gt;
                    &lt;App AppUserModelId="Citrix.Workspace_8r8r2r2r2r2r2!App"/&gt;  
			          &lt;/AllowedApps&gt;
            &lt;/AllAppsList&gt;         
            &lt;StartLayout&gt;
				&lt;![CDATA[&lt;LayoutModificationTemplate xmlns:defaultlayout="http://schemas.microsoft.com/Start/2014/FullDefaultLayout" xmlns:start="http://schemas.microsoft.com/Start/2014/StartLayout" Version="1" xmlns="http://schemas.microsoft.com/Start/2014/LayoutModification"&gt;
  &lt;LayoutOptions StartTileGroupCellWidth="6" /&gt;
  &lt;DefaultLayoutOverride&gt;
    &lt;StartLayoutCollection&gt;
      &lt;defaultlayout:StartLayout GroupCellWidth="6"&gt;
        &lt;start:Group Name="Kiosk"&gt;
          &lt;start:Tile AppUserModelID="Microsoft.MicrosoftEdge_8wekyb3d8bbwe!MicrosoftEdge" Size="2x2" Column="0" Row="0" /&gt;
          &lt;start:Tile AppUserModelID="Citrix.Workspace_8r8r2r2r2r2r2!App" Size="2x2" Column="2" Row="0" /&gt;
        &lt;/start:Group&gt;
      &lt;/defaultlayout:StartLayout&gt;
    &lt;/StartLayoutCollection&gt;
  &lt;/DefaultLayoutOverride&gt;
&lt;/LayoutModificationTemplate&gt;
                ]]&gt;
			&lt;/StartLayout&gt;
            &lt;Taskbar ShowTaskbar="true"/&gt;
        &lt;/Profile&gt;
    &lt;/Profiles&gt;
    &lt;Configs&gt;
        &lt;Config&gt;
            &lt;AutoLogonAccount/&gt;
            &lt;DefaultProfile Id="{2d37d0db-19a0-48ad-8b8b-976a7cbf556d}"/&gt;
        &lt;/Config&gt;
    &lt;/Configs&gt;
&lt;/AssignedAccessConfiguration&gt;
